 dest=Path(m['output']);assert dest==ROOT/'Dane/db/TEST_X10'
 master=read(B/'manifest.json');assert pins(Path(master['source']))==master['source_hashes'],'Immutable X8 source changed'
 before=pins(dest);old=dest/'TEST_X8.xml';new=dest/'TEST_X10.xml'
 assert not old.exists()and new.exists()
 raw=new.read_bytes();root=ET.fromstring(raw)
 assert root.find("./string[@id='name']").get('value')=='TEST_X10'
 root.find("./string[@id='name']").set('value','TEST_X10');root.find("./string[@id='description']").text='TEST_X10'
