 (dest/'README.md').write_text('TEST_X10\n\nSerbia, Rumunia, RPA i Rosja: klasyczne liczebnosci FM08; dwa grywalne poziomy w kazdym kraju. 154 kluby, 4230 potwierdzonych zawodnikow, 317 wypozyczen.\n\nKontrole natywne i niezalezny odczyt PASS. Zapis SI, nowa kariera i symulacja sezonu: oczekuja na test uzytkownika. Szczegoly: FmLauncher/data/research/SERBIA_ROMANIA_RSA_RUSSIA_X10_20261111/REPORT.md.\n',encoding='utf-8')
 after=pins(dest);changes={k:dict(before=before.get(k),after=after.get(k))for k in set(before)|set(after)if before.get(k)!=after.get(k)}
 assert set(changes)=={'TEST_X10.xml','README.md'}
