 r=dict(status='native_ready_for_user_SI_and_game_test',database=str(dest),name='TEST_X10',source='TEST_X8 immutable accepted snapshot; never X9',countries=stats,counts=m['counts'],native=True,SI=False,new_career=False,season=False,metadata_only_changes=changes,all_DAT_unchanged_after_native_inverse_verification=True,output_hashes=after,source_X8_unchanged=True,structure_proof=str(B/'structure-independent.json'),roster_proof=str(P/'independent-verification.json'),pilot_proof=m['pilot_verification_path'],negative_cases=7,source_gaps=m['source_gaps_count'],all_project_sugar_daddy_off=324,FC_Jurong_aliases_disabled=15,Thailand=False,source_reference_date='2026-11-11',real_season='2026/27',preserve_empty_rosters=m['structural_only_club_uids'],teleoptik_contract_family=read(B/'teleoptik-native-contract-family.json'))
 dump(B/'publication.json',r)
 master.update(status=r['status'],output_database_created=True,native=True,SI=False,new_career=False,season=False,counts=m['counts'],output_hashes=after,publication=str(B/'publication.json'));dump(B/'manifest.json',master)
 lines=['# TEST_X10 — gotowa do testu SI i nowej kariery','','Podstawa: zaakceptowana TEST_X8. Tajlandia/X9 pozostają odłożone. Aktualizacja obejmuje dwa grywalne poziomy w każdym z czterech krajów, w klasycznych liczebnościach FM08.','','| Kraj | Kluby | Zawodnicy | Istniejący | Nowi | Wypożyczenia |','|---|---:|---:|---:|---:|---:|']
 for x in stats:lines.append('| '+x['country']+' | '+' | '.join(str(x[k])for k in ['clubs','players','existing','new','loans'])+' |')
 lines+=['','Łącznie: 154 kluby, 4230 osób, 317 wypożyczeń. 102 nowe TEAM, 101 nowych rodzin (jedna rezerwa dzieli rodzinę rodzica), 126 nowych rekordów stadionów; trzy wspólne stadiony ujednolicone referencją (trzy nieużyte rekordy zachowane dla stabilności indeksów). 53 jawne braki danych stadionów pozostawione bez fikcyjnych szczegółów.','','## Sprawdzenie','','Native: PASS. Pilot 221 osób i 126 wypożyczeń: PASS. Pełny import oraz niezależny odczyt i odwrócenie zmian PEOPLE/SERVER/CLIENT: PASS. Wszystkie istniejące atrybuty i osobowości zachowane. 54/54 sprawdzeń liczebności obu form struktury: PASS. Sugar Daddy jawnie OFF i niezależnie odczytane we wszystkich 324 projektowych rodzinach. 15 aliasów FC Jurong UID1000037 wyłączono z zachowaniem UTF16LE/BOM i japońskiego UID107280. Metadane zmieniają tylko XML/README po kontroli natywnej; żaden DAT nie zmienił się po tej kontroli.','','SI, nowa kariera i sezon: OCZEKUJĄ na test użytkownika, osobne statusy.','','## Adaptacje i ograniczenia','','Serbia 12+18; Rumunia 18+18+18; Rosja 16+22; RPA 16+16 (dwa poziomy, natywna organizacja NFD zachowana). Dobór i kaskady według końca poprzedniego sezonu oraz oficjalnych decyzji/licencji. Wszystkie decyzje źródłowe i dokładne UID są w selection-decisions, club-plan, structure-config i źródłach. Niższe niegrywalne pule sprawdzono technicznie i dostosowano do bramek silnika; nie deklarujemy aktualnych pełnych kadr tych pul.','','417 jawnych luk źródłowych/odroczeń. KSE Targu Secuiesc i North West University mają zerowy import osób; istniejących osób nie usuwano. Pozostałe niepełne kadry pozostawiono zgodnie z decyzją użytkownika, bez szukania na siłę. 22 potwierdzone techniczne duplikaty wyłączono; niejednoznaczne tożsamości zachowano/odroczono. Teleoptik ma własny TEAM4043/UID136465 i własną rodzinę3832, ale natywnie wspólną kontraktową rodzinę Partizana1490. Zachowano to powiązanie bez oznaczania klubu jako rezerwy i bez mieszania OwnerTEAM/rosterów.','','Kalendarze i zasady silnika pozostają klasyczne FM08. Wypożyczenia od krajowych i zagranicznych właścicieli; nieznane kwoty opcji nie są wymyślane, obowiązek wykupu pominięty. Oceny istniejących osób zachowane, nowe są oszacowaniami według wspólnego modelu. Messi pozostaje poza zakresem poprawki.','','## Test użytkownika','','Otworzyć TEST_X10 w edytorze SI, zapisać i zamknąć. Utworzyć nową karierę z Serbią, Rumunią, RPA i Rosją na dwóch dostępnych poziomach każdego kraju. Sprawdzić obecność wszystkich krajów, zakończenie tworzenia, tabele i terminarze, a następnie zachować osobny zapis kontrolny przed symulacją sezonu.','','Pełne dowody i piny: publication.json, structure-independent.json, prepared/independent-verification.json, prepared/full-native.json i sources/.']
 (B/'REPORT.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
 (B/'WZNOWIENIE.md').write_text('# TEST_X10 — native PASS, gotowa do testu użytkownika\n\nBaza: J:/FM08dev/Dane/db/TEST_X10. Serbia/Rumunia/RPA/Rosja; 154 kluby, 4230 osób, 317 wypożyczeń. Native/pilot/inverse PASS. SI/kariera/sezon oczekują osobno. Nie powtarzać pełnego importu ani nie nadpisywać X10. Podstawa X8 niezmieniona, X9/Tajlandia odłożone. Szczegóły REPORT.md i publication.json. Teleoptik: osobny TEAM/UID, natywnie rodzina kontraktowa Partizana1490; jawny dowód teleoptik-native-contract-family.json.\n',encoding='utf-8')
